{"source":"#!/usr/bin/env python3
"""Summarize a CSV with category,amount,status — include only paid rows."""

import csv
import json
import sys
from decimal import Decimal, ROUND_HALF_UP


def summarize(input_path: str) -> dict:
    categories: dict[str, Decimal] = {}

    with open(input_path, newline="", encoding="utf-8") as fh:
        reader = csv.DictReader(fh)
        for row in reader:
            status = row.get("status", "").strip().casefold()
            if status != "paid":
                continue

            # Normalize category: collapse whitespace, casefold, blank → uncategorized
            raw_cat = row.get("category", "")
            cat = " ".join(raw_cat.split()).casefold()
            if cat == "":
                cat = "uncategorized"

            # Parse and round amount
            amount = Decimal(row["amount"].strip())
            rounded = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

            categories[cat] = categories.get(cat, Decimal("0")) + rounded

    # Build sorted output
    sorted_cats = sorted(categories.items(), key=lambda kv: kv[0])
    result = {
        "categories": [
            {"category": name, "total": str(total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))}
            for name, total in sorted_cats
        ],
        "total": str(
            sum((v.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP) for v in categories.values()), Decimal("0"))
            .quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        ),
    }
    return result


def main() -> None:
    if len(sys.argv) < 2:
        print("Usage: solution.py <input.csv>", file=sys.stderr)
        sys.exit(1)
    result = summarize(sys.argv[1])
    print(json.dumps(result))


if __name__ == "__main__":
    main()"}

